    AND MST.Cont_Id    =MC.Id
    AND MST.Dept_RId   =CE.Id
    AND MST.Unit_RId   =CN.Id
    AND MST.Oper_RId   =CR.Id
    AND MST.Src_Id     =SC.Id
    AND MST.Trt_Id     =TR.Id
    AND MST.Method_Id  =CM.Id
    AND MST.Contract_Id=CC.Id
    AND MST.KeyType_Id =CK.Id
    AND MST.Status_Id  =CS.Id
    AND TRN.Mst_Id     =MST.Id
    AND TRN.Cont_RId   =TC.Id
    AND TRN.Serv_Id    =MS.Id
    AND TRN.Acc_Id     =AA.Id
    AND TRN.Item_Id    =ST.Id
    AND TRN.Curn_Id    =MR.Id
    AND TRN.LType_Id   =LT.Id
    AND TRN.Type_Id    =CT.Id
    AND TRN.Loc_Id     =CL.Id
    AND TRN.Unit_Id    =UU.Id;

CREATE OR REPLACE VIEW Fin_VDbtRec_Mst AS
 SELECT 
        MST.Id       ,
        CD.Id          Dept_Id     , CD.Name     Dept_Name     ,
        CU.Id          Unit_Id     , CU.Name     Unit_Name     ,
        CO.Id          Oper_Id     , CO.Name     Oper_Name     ,
        CP.Id          Period_Id   , CP.Name     Period_Name   ,
        SC.Id          Src_Id      , SC.Name     Src_Name      ,
        TR.Id          Trt_Id      , TR.Name     Trt_Name      ,
        CS.Id          Status_Id   , CS.Name     Status_Name   ,
        CM.Id          Method_Id   , CM.Name     Method_Name   ,
        MC.Id          Cont_Id     , MC.Name     Cont_Name     ,
        CC.Id          Contract_Id , CC.Name     Contract_Name ,
        CK.Id          KeyType_Id  , CK.Name     KeyType_Name  ,
        CU1.Id         Curn_Id     , CU1.Name    Curn_Name     ,
        MST.Vhr_Id   , MST.Bank_Id , MST.Ord_Id, MST.Num       ,
        MST.ddate    , MST.DueDate , MST.RefNum,
        MST.KeyNum   , MST.KeyDate , MST.Rem   , MST.Note      ,
        MST.Curn_Rate, MST.CAmt    , MST.Amt   ,
        MST.ACAmt    , MST.AAmt    , MST.APCAmt, MST.APAmt
   FROM Fin_MRec           MST,
        Cpy_Period              CP ,
        Cpy_Dept                CD ,
        Cpy_Unit                CU ,
        Cpy_Oper                CO ,
        Mng_Cont                MC ,
        Phs_Cod_Src             SC ,
        Fin_Cod_Trt             TR ,
        Fin_Cod_Method          CM ,
        Fin_Cod_Contract        CC ,
        Fin_Cod_KeyType         CK ,
        Fin_Cod_Status          CS ,
        Mng_Curn                CU1
  WHERE MST.Period_Id   = CP.Id
    AND MST.Dept_Id     = CD.Id
    AND MST.Unit_Id     = CU.Id
    AND MST.Oper_Id     = CO.Id
    AND MST.Cont_Id     = MC.Id
    AND MST.Src_Id      = SC.Id
    AND MST.Trt_Id      = TR.Id
    AND MST.Method_Id   = CM.Id
    AND MST.Contract_Id = CC.Id
    AND MST.KeyType_Id  = CK.Id
    AND MST.Status_Id   = CS.Id
    AND MST.Curn_Id     = CU1.Id;

CREATE OR REPLACE VIEW Fin_VCrdRec_Mst AS
 SELECT 
        MST.Id        ,
        CE.Id           Dept_Id    , CE.Name     Dept_Name     ,
        CN.Id           Unit_Id    , CN.Name     Unit_Name     ,
        CR.Id           Oper_Id    , CR.Name     Oper_Name     ,
        CP.Id           Period_Id  , CP.Name     Period_Name   ,
        SC.Id           Src_Id     , SC.Name     Src_Name      ,
        TR2.Id          Trt_Id     , TR2.Name    Trt_Name      ,
        CS.Id           Status_Id  , CS.Name     Status_Name   ,
        CM.Id           Method_Id  , CM.Name     Method_Name   ,
        MC2.Id          Cont_Id    , MC2.Name    Cont_Name     ,
        CC.Id           Contract_Id, CC.Name     Contract_Name ,
        CK.Id           KeyType_Id , CK.Name     KeyType_Name  ,
        CU2.Id          Curn_Id    , CU2.Name    Curn_Name     ,
        MST.Vhr_Id    , MST.Bank_Id, MST.Ord_Id, MST.Num       ,
        MST.ddate     , MST.DueDate, MST.RefNum,
        MST.KeyNum    , MST.KeyDate, MST.Rem   , MST.Note      ,
        MST.Curn_RRate  Curn_Rate  , MST.RCAmt   CAmt          , MST.RAmt Amt,
        MST.ACAmt     , MST.AAmt   , MST.APCAmt, MST.APAmt
   FROM Fin_MRec    MST,
        Cpy_Period       CP ,
        Cpy_Dept         CE ,
        Cpy_Unit         CN ,
        Cpy_Oper         CR ,
        Mng_Cont         MC2,
        Phs_Cod_Src      SC ,
        Fin_Cod_Trt      TR2,
        Fin_Cod_Method   CM ,
        Fin_Cod_Contract CC ,
        Fin_Cod_KeyType  CK ,
        Fin_Cod_Status   CS ,
        Mng_Curn         CU2 
  WHERE MST.Period_Id   = CP.Id
    AND MST.Dept_RId    = CE.Id
    AND MST.Unit_RId    = CN.Id
    AND MST.Oper_RId    = CR.Id
    AND MST.Cont_RId    = MC2.Id
    AND MST.Src_Id      = SC.Id
    AND MST.Trt_RId     = TR2.Id
    AND MST.Method_Id   = CM.Id
    AND MST.Contract_Id = CC.Id
    AND MST.KeyType_Id  = CK.Id
    AND MST.Status_Id   = CS.Id
    AND MST.Curn_RId    = CU2.Id;

CREATE OR REPLACE VIEW Fin_VAll_Mst AS
