CREATE OR REPLACE VIEW Fin_VSumInv AS
 SELECT
       Id           ,
       Dept_Id      , Dept_Name    , Unit_Id      , Unit_Name    ,
       Oper_Id      , Oper_Name    , Period_Id    , Period_Name  ,
       Dept_RId     , Dept_RName   , Unit_RId     , Unit_RName   ,
       Oper_RId     , Oper_RName   , Src_Id       , Src_Name     ,
       Trt_Id       , Trt_Name     , Status_Id    , Status_Name  ,
       Method_Id    , Method_Name  , Cont_Id      , Cont_Name    ,
       Contract_Id  , Contract_Name, KeyType_Id   , KeyType_Name ,
       Vhr_Id       , Bank_Id      , Ord_Id       , Num          , ddate  , DueDate , RefNum,
       KeyNum       , KeyDate      , Rem          , Note         ,
       ACAmt        , AAmt         , APCAmt       , APAmt        ,
       TRN_Curn_Id  , TRN_Curn_Name, Curn_Rate    ,
       SUM(Qnt      ) TRN_Qnt      ,
       Sum(CAmt     ) TRN_CAmt     ,
       SUM(Amt      ) TRN_Amt      ,
       SUM(Vat_Value) TRN_Vat_Value,
       SUM(Net_Amt  ) TRN_Net_Amt  ,
       SUM(Net_CAmt ) TRN_Net_CAmt
   FROM Fin_VInv_Mst_TRN
   GROUP BY
       Id           ,
       Dept_Id      , Dept_Name    , Unit_Id      , Unit_Name    ,
       Oper_Id      , Oper_Name    , Period_Id    , Period_Name  ,
       Dept_RId     , Dept_RName   , Unit_RId     , Unit_RName   ,
       Oper_RId     , Oper_RName   , Src_Id       , Src_Name     ,
       Trt_Id       , Trt_Name     , Status_Id    , Status_Name  ,
       Method_Id    , Method_Name  , Cont_Id      , Cont_Name    ,
       Contract_Id  , Contract_Name, KeyType_Id   , KeyType_Name ,
       Vhr_Id       , Bank_Id      , Ord_Id       , Num          , ddate  , DueDate , RefNum,
       KeyNum       , KeyDate      , Rem          , Note         ,
       ACAmt        , AAmt         , APCAmt       , APAmt        ,
       TRN_Curn_Id  , TRN_Curn_Name, Curn_Rate;

