         TRN_Net_Amt  ,
         TRN_Net_CAmt
    FROM Fin_VSumDbt
  UNION ALL
  SELECT 'CREDIT'         AS Doc_Type     ,
         Id                , Vhr_Id       ,
         Dept_Id           , Dept_Name    ,
         Unit_Id           , Unit_Name    ,
         Oper_Id           , Oper_Name    ,
         Period_Id         , Period_Name  ,
