         -1*TRN_Qnt       AS TRN_Qnt      ,
         -1*TRN_CAmt      AS TRN_CAmt     ,
         -1*TRN_Amt       AS TRN_Amt      ,
         -1*TRN_Vat_Value AS TRN_Vat_Value,
         -1*TRN_Net_Amt   AS TRN_Net_Amt  ,
         -1*TRN_Net_CAmt  AS TRN_Net_CAmt
    FROM Fin_VSumCrd
  UNION ALL
  SELECT 'EXPENSE'        AS Doc_Type     ,
         Id                , Vhr_Id       ,
         Dept_Id           , Dept_Name    ,
         Unit_Id           , Unit_Name    ,
         Oper_Id           , Oper_Name    ,
         Period_Id         , Period_Name  ,
         Dept_RId          , Dept_RName   ,
         Unit_RId          , Unit_RName   ,
         Oper_RId          , Oper_RName   ,
         Src_Id            , Src_Name     ,
         Trt_Id            , Trt_Name     ,
         Status_Id         , Status_Name  ,
         Method_Id         , Method_Name  ,
         Cont_Id           , Cont_Name    ,
         Contract_Id       , Contract_Name,
         KeyType_Id        , KeyType_Name ,
         Bank_Id           , Ord_Id       ,
         Num               , ddate        ,
         DueDate           , RefNum       ,
         KeyNum            , KeyDate      ,
         Rem               , Note         ,
         ACAmt             , AAmt         ,
         APCAmt            , APAmt        ,
         TRN_Curn_Id       , TRN_Curn_Name, Curn_Rate,
         -1*TRN_Qnt       AS TRN_Qnt      ,
         -1*TRN_CAmt      AS TRN_CAmt     ,
         -1*TRN_Amt       AS TRN_Amt      ,
         -1*TRN_Vat_Value AS TRN_Vat_Value,
         -1*TRN_Net_Amt   AS TRN_Net_Amt  ,
         -1*TRN_Net_CAmt  AS TRN_Net_CAmt
    FROM Fin_VSumExp
  UNION ALL
  SELECT 'REC_DEBIT' AS Doc_Type     ,
         Id           , Vhr_Id       ,
         Dept_Id      , Dept_Name    ,
         Unit_Id      , Unit_Name    ,
         Oper_Id      , Oper_Name    ,
         Period_Id    , Period_Name  ,
         CAST(0 AS DECIMAL(38,10)) AS Dept_RId, CAST('-' AS VARCHAR(200)) AS Dept_RName,
         CAST(0 AS DECIMAL(38,10)) AS Unit_RId, CAST('-' AS VARCHAR(200)) AS Unit_RName,
         CAST(0 AS DECIMAL(38,10)) AS Oper_RId, CAST('-' AS VARCHAR(200)) AS Oper_RName,
         Src_Id       , Src_Name     ,
         Trt_Id       , Trt_Name     ,
         Status_Id    , Status_Name  ,
         Method_Id    , Method_Name  ,
         Cont_Id      , Cont_Name    ,
         Contract_Id  , Contract_Name,
         KeyType_Id   , KeyType_Name ,
         Bank_Id      , Ord_Id       ,
         Num          , ddate        ,
         DueDate      , RefNum       ,
         KeyNum       , KeyDate      ,
         Rem          , Note         ,
         ACAmt        , AAmt         ,
         APCAmt       , APAmt        ,
         Curn_Id     AS TRN_Curn_Id  , Curn_Name AS TRN_Curn_Name, Curn_Rate,
         1           AS TRN_Qnt      ,
         CAmt        AS TRN_CAmt     ,
         Amt         AS TRN_Amt      ,
         0           AS TRN_Vat_Value,
         Amt         AS TRN_Net_Amt  ,
         CAmt        AS TRN_Net_CAmt
    FROM Fin_VDbtRec_Mst
  UNION ALL
  SELECT 'REC_CREDIT' AS Doc_Type    ,
         Id           , Vhr_Id       ,
         Dept_Id      , Dept_Name    ,
         Unit_Id      , Unit_Name    ,
         Oper_Id      , Oper_Name    ,
         Period_Id    , Period_Name  ,
         CAST(0 AS DECIMAL(38,10)) AS Dept_RId, CAST('-' AS VARCHAR(200)) AS Dept_RName,
         CAST(0 AS DECIMAL(38,10)) AS Unit_RId, CAST('-' AS VARCHAR(200)) AS Unit_RName,
         CAST(0 AS DECIMAL(38,10)) AS Oper_RId, CAST('-' AS VARCHAR(200)) AS Oper_RName,
         Src_Id       , Src_Name     ,
         Trt_Id       , Trt_Name     ,
         Status_Id    , Status_Name  ,
         Method_Id    , Method_Name  ,
         Cont_Id      , Cont_Name    ,
         Contract_Id  , Contract_Name,
         KeyType_Id   , KeyType_Name ,
         Bank_Id      , Ord_Id       ,
         Num          , ddate        ,
         DueDate      , RefNum       ,
         KeyNum       , KeyDate      ,
         Rem          , Note         ,
         ACAmt        , AAmt         ,
         APCAmt       , APAmt        ,
         Curn_Id     AS TRN_Curn_Id  , Curn_Name AS TRN_Curn_Name, Curn_Rate,
         1           AS TRN_Qnt      ,
         -1*CAmt     AS TRN_CAmt     ,
         -1*Amt      AS TRN_Amt      ,
         0           AS TRN_Vat_Value,
         -1*Amt      AS TRN_Net_Amt  ,
         -1*CAmt     AS TRN_Net_CAmt
    FROM Fin_VCrdRec_Mst;
